39	/**
40	 * Calculates the cost of an API call based on the model and token usage.
41	 *
42	 * @param {string} modelName The name of the model used.
43	 * @param {ProviderConfig} config The provider configuration.
44	 * @param {number | undefined} promptTokens The number of tokens in the prompt.
45	 * @param {number | undefined} completionTokens The number of tokens in the completion.
46	 * @param {ProviderModel[]} models An array of available models with their costs.
47	 * @returns {number | undefined} The calculated cost, or undefined if it can't be calculated.
48	 */
49	export function calculateCost(
50	  modelName: string,
51	  config: ProviderConfig,
52	  promptTokens: number | undefined,
53	  completionTokens: number | undefined,
54	  models: ProviderModel[],
55	): number | undefined {
56	  if (
57	    !Number.isFinite(promptTokens) ||
58	    !Number.isFinite(completionTokens) ||
59	    typeof promptTokens === 'undefined' ||
60	    typeof completionTokens === 'undefined'
61	  ) {
62	    return undefined;
63	  }
64	
65	  const model = models.find((m) => m.id === modelName);
66	  if (!model || !model.cost) {
67	    return undefined;
68	  }
69	
70	  const longContextCost =
71	    model.cost.longContext && promptTokens > model.cost.longContext.threshold
72	      ? model.cost.longContext
73	      : undefined;
74	  const inputCost = config.cost ?? longContextCost?.input ?? model.cost.input;
75	  const outputCost = config.cost ?? longContextCost?.output ?? model.cost.output;
76	  return inputCost * promptTokens + outputCost * completionTokens;
77	}
