79	/**
80	 * Checks if a string looks like it's attempting to be JSON.
81	 * This helps distinguish between actual JSON attempts and plain text that happens to start/end with brackets.
82	 */
83	function looksLikeJson(prompt: string): boolean {
84	  const trimmed = prompt.trim();
85	
86	  // Objects starting with { are almost always JSON
87	  if (trimmed.startsWith('{') && trimmed.endsWith('}')) {
88	    return true;
89	  }
90	
91	  // Arrays starting with [ need more careful checking
92	  if (trimmed.startsWith('[') && trimmed.endsWith(']')) {
93	    // Check if the character after [ suggests it's JSON
94	    // Valid JSON array starts: ", {, [, whitespace, number, or true/false/null
95	    const afterBracket = trimmed.slice(1).trimStart();
96	    if (
97	      afterBracket.startsWith('"') ||
98	      afterBracket.startsWith('{') ||
99	      afterBracket.startsWith('[') ||
100	      /^[\d-]/.test(afterBracket) || // number
101	      /^(true|false|null)/.test(afterBracket) // boolean or null
102	    ) {
103	      return true;
104	    }
105	    // If it's just whitespace or empty, it might be JSON
106	    if (afterBracket.length === 0 || /^\s+$/.test(afterBracket)) {
107	      return true;
108	    }
109	    // Otherwise, it's likely plain text (e.g., [INST]...[/INST])
110	    return false;
111	  }
112	
113	  return false;
114	}
