116	/**
117	 * Parses a chat prompt string into a structured format.
118	 *
119	 * @template T The expected return type of the parsed prompt.
120	 * @param {string} prompt The input prompt string to parse.
121	 * @param {T} defaultValue The default value to return if parsing fails.
122	 * @returns {T} The parsed prompt or the default value.
123	 * @throws {Error} If the prompt is invalid YAML or JSON (when required).
124	 */
125	export function parseChatPrompt<T>(prompt: string, defaultValue: T): T {
126	  const trimmedPrompt = prompt.trim();
127	  if (trimmedPrompt.startsWith('- role:')) {
128	    try {
129	      // Try YAML - some legacy OpenAI prompts are YAML :(
130	      return yaml.load(prompt) as T;
131	    } catch (err) {
132	      throw new Error(`Chat Completion prompt is not a valid YAML string: ${err}\n\n${prompt}`);
133	    }
134	  } else {
135	    try {
136	      // Try JSON
137	      return JSON.parse(prompt) as T;
138	    } catch (err) {
139	      if (getEnvBool('PROMPTFOO_REQUIRE_JSON_PROMPTS') || looksLikeJson(trimmedPrompt)) {
140	        throw new Error(`Chat Completion prompt is not a valid JSON string: ${err}\n\n${prompt}`);
141	      }
142	      // Fall back to the provided default value
143	      return defaultValue;
144	    }
145	  }
146	}
