182	 * the object form ({ type: 'function', function: { name } }).
183	 */
184	export function isOpenAIToolChoice(obj: unknown): obj is OpenAIToolChoice {
185	  if (typeof obj === 'string') {
186	    return ['auto', 'none', 'required'].includes(obj);
187	  }
188	  if (typeof obj === 'object' && obj !== null) {
189	    const candidate = obj as Record<string, unknown>;
190	    if (
191	      candidate.type === 'function' &&
192	      typeof candidate.function === 'object' &&
193	      candidate.function !== null
194	    ) {
195	      const fn = candidate.function as Record<string, unknown>;
196	      return typeof fn.name === 'string';
197	    }
198	  }
199	  return false;
200	}
