154	export function outputFromMessage(message: Anthropic.Messages.Message, showThinking: boolean) {
155	  const hasToolUse = message.content.some((block) => block.type === 'tool_use');
156	  const hasThinking = message.content.some(
157	    (block) => block.type === 'thinking' || block.type === 'redacted_thinking',
158	  );
159	
160	  if (hasToolUse || hasThinking) {
161	    return message.content
162	      .map((block) => {
163	        if (block.type === 'text') {
164	          return block.text;
165	        } else if (block.type === 'thinking' && showThinking) {
166	          return `Thinking: ${block.thinking}\nSignature: ${block.signature}`;
167	        } else if (block.type === 'redacted_thinking' && showThinking) {
168	          return `Redacted Thinking: ${block.data}`;
169	        } else if (block.type !== 'thinking' && block.type !== 'redacted_thinking') {
170	          return JSON.stringify(block);
171	        }
172	        return '';
173	      })
174	      .filter((text) => text !== '')
175	      .join('\n\n');
176	  }
177	  return message.content
178	    .map((block) => {
179	      return (block as Anthropic.Messages.TextBlock).text;
180	    })
181	    .join('\n\n');
182	}
