35	/**
36	 * Calculate DeepSeek cost based on model name and token usage
37	 */
38	export function calculateDeepSeekCost(
39	  modelName: string,
40	  config: any,
41	  promptTokens?: number,
42	  completionTokens?: number,
43	  cachedTokens?: number,
44	): number | undefined {
45	  if (!promptTokens || !completionTokens) {
46	    return undefined;
47	  }
48	
49	  const model = DEEPSEEK_CHAT_MODELS.find((m) => m.id === modelName);
50	  if (!model || !model.cost) {
51	    // Use default pricing for unknown models
52	    return calculateCost(modelName, config, promptTokens, completionTokens, DEEPSEEK_CHAT_MODELS);
53	  }
54	
55	  const uncachedPromptTokens = cachedTokens ? promptTokens - cachedTokens : promptTokens;
56	  const inputCost = config.cost ?? model.cost.input;
57	  const outputCost = config.cost ?? model.cost.output;
58	  const cacheReadCost = config.cacheReadCost ?? model.cost.cache_read;
59	
60	  const inputCostTotal = inputCost * uncachedPromptTokens;
61	  const cacheReadCostTotal = cachedTokens ? cacheReadCost * cachedTokens : 0;
62	  const outputCostTotal = outputCost * completionTokens;
63	
64	  logger.debug(
65	    `DeepSeek cost calculation for ${modelName}: ` +
66	      `promptTokens=${promptTokens}, completionTokens=${completionTokens}, ` +
67	      `cachedTokens=${cachedTokens || 0}, ` +
68	      `inputCost=${inputCostTotal}, cacheReadCost=${cacheReadCostTotal}, outputCost=${outputCostTotal}`,
69	  );
70	
71	  return inputCostTotal + cacheReadCostTotal + outputCostTotal;
72	}
